INSERT INTO `sys_app_info` VALUES (1926294804323684352, 100, 'app', '系统管理', 'system', 0, '/system', NULL, '1.0.0', '{\"header\":[],\"main\":[{\"value\":\"一、主要功能\\n\",\"bold\":true},{\"value\":\"1、基础管理：字典管理，应用管理，配置管理\\n2、组织管理：机构管理，用户管理，角色管理，分组管理，岗位管理\\n3、权限管理：用户权限，角色权限\\n4、统一消息：分类管理、模版管理、消息管理、我的消息\\n5、租户管理：租户维护\\n6、运维管理：操作日志，访问统计，动态订阅，联系我们\",\"bold\":false}],\"footer\":[]}', 'SettingOutlined', NULL, NULL, NULL, 100, NULL, 'pc', 1, 0, 3, NULL, '2025-05-24 23:10:45', 10000, '2025-10-17 20:31:24', 10000);
