INSERT INTO `sys_app_info` VALUES (1979369130308063232, 100, 'platform', 'Uinone Cloud', 'unione-cloud', 0, NULL, NULL, '0.0.1', '{\"header\":[],\"main\":[{\"value\":\"项目简介:\\n\",\"size\":13,\"bold\":true,\"color\":\"#0665cb\",\"italic\":false},{\"value\":\"unione cloud 是一个企业级统一低代码开发平台，旨在为企业提供一站式低代码建站服务。通过可视化拖拽、配置等方式，帮助企业快速构建各类业务应用，大幅降低开发成本和技术门槛。\\n\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n功能特性:\",\"size\":13,\"bold\":true,\"color\":\"#0665cb\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"可视化开发\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：拖拽式界面设计，所见即所得\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"组件化架构\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：丰富的功能组件库，支持自定义扩展\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"多模块设计\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：基于微服务架构，各模块松耦合高内聚\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"安全认证\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：完善的用户认证与权限管理体系\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"API管理\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：统一的接口管理与文档自动化生成\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"数据管理\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：灵活的数据模型设计与管理\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"\\n\",\"color\":\"#353131\"},{\"value\":\"- \",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false},{\"value\":\"工作流支持\",\"size\":13,\"bold\":true,\"color\":\"#353131\",\"italic\":false},{\"value\":\"：可视化工作流设计与运行\",\"size\":13,\"bold\":false,\"color\":\"#353131\",\"italic\":false}],\"footer\":[]}', 'CloudOutlined', NULL, NULL, NULL, 0, NULL, 'pc', 0, 0, 2, NULL, '2025-10-18 10:09:10', 10000, '2025-10-18 10:52:00', 10000);
INSERT INTO `sys_app_info` VALUES (1979370471424184320, 100, 'platform', 'Union Admin', 'unione-admin', 0, NULL, NULL, '0.0.1', '{\"header\":[],\"main\":[{\"value\":\"项目简介\",\"size\":13,\"bold\":true,\"color\":\"#0572e6\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"unione-admin-vue 是一个基于 Vue 3、TypeScript 和 Vite 构建的现代化管理系统前端框架，为企业级应用提供高效、灵活、美观的管理界面解决方案。\\n\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n主要特性\",\"size\":13,\"bold\":true,\"color\":\"#0572e6\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 🚀 \",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\"技术栈\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：Vue 3 + TypeScript + Vite + Vuex + Vue Router\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 🎨 \",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\"UI 设计\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：响应式布局，优雅的视觉体验\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 🔒\",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\" \",\"size\":13,\"bold\":true,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\"权限管理\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：完善的权限控制体系\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 📊\",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\" \",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"数据可视化\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：集成多种图表库\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 🔧 \",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\"组件化\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：丰富的可复用组件\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"-\",\"size\":13,\"bold\":false,\"color\":\"rgb(242, 133, 140)\",\"italic\":false},{\"value\":\" 🛠️ \",\"size\":13,\"bold\":false,\"color\":\"rgb(209, 211, 219)\",\"italic\":false},{\"value\":\"开发体验\",\"size\":13,\"bold\":true,\"color\":\"#323232\",\"italic\":false},{\"value\":\"：完整的开发工具链，支持热重载、TypeScript 类型检查等\",\"size\":13,\"bold\":false,\"color\":\"#323232\",\"italic\":false},{\"value\":\"\\n\"}],\"footer\":[]}', 'FundProjectionScreenOutlined', NULL, NULL, NULL, 5, NULL, 'pc', 0, 0, 2, NULL, '2025-10-18 10:14:30', 10000, '2025-10-18 10:51:34', 10000);
INSERT INTO `sys_app_info` VALUES (1979371119309934592, 100, 'service', 'Unione Cms', 'unione-cms', 0, NULL, NULL, '0.0.1', '{\"header\":[],\"main\":[{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"项目简介:\",\"size\":13,\"bold\":true,\"color\":\"rgb(6, 101, 203)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"Unione CMS是基于Unione Cloud构建的内容管理系统，提供快速搭建各类网站的能力，内置丰富的网站模板。本项目致力于为用户提供高效、灵活、易用的内容管理解决方案，适用于企业官网、门户网站、内容平台等多种场景。\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"主要功能\",\"size\":13,\"bold\":true,\"color\":\"rgb(6, 101, 203)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"站点管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：多站点统一管理，支持站点创建、编辑、删除等操作\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点域名绑定\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持多个域名绑定到不同站点\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"栏目管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：灵活的栏目结构设计，支持无限层级分类\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：富文本编辑器，支持图文混排、视频嵌入等\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容发布\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：工作流支持，多级审核机制\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容审核\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持多级审核流程，确保内容质量\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容预览\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：实时预览内容展示效果\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"资源管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：统一的媒体资源管理系统\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"开发管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持资源在线开发，调试，预览；支持版本管理。\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"资源导入/导出\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持批量资源操作\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点静态化\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持整站静态化，提升访问性能\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点导出\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持站点完整导出，便于迁移和备份\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"listType\":\"ul\",\"listStyle\":\"disc\"}],\"footer\":[]}', 'GlobalOutlined', NULL, NULL, NULL, 15, NULL, 'pc', 0, 0, 1, NULL, '2025-10-18 10:17:04', 10000, '2025-10-19 21:49:40', 10000);

-- ----------------------------
-- Table structure for sys_app_theme
-- ----------------------------
DROP TABLE IF EXISTS `sys_app_theme`;
CREATE TABLE `sys_app_theme`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '主题名称，字典UNIONETHEME default：默认',
  `APP_ID` bigint(0) NULL DEFAULT NULL COMMENT '应用ID',
  `IS_GLOBAL` int(0) NOT NULL COMMENT '是否全局，字典 TUREORFALSE 1是，0否。 如果设置了全局主题，则所有应用统一使用该主题',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '主题配置，json格式存储',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：应用主题' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_app_theme
-- ----------------------------

-- ----------------------------
-- Table structure for sys_change_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_change_log`;
CREATE TABLE `sys_change_log`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `VERS_NO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '版本号',
  `VERS_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '版本类型，字典VERSTYPE release：发布，dev：开发，beta：内测',
  `VERS_DESC` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '版本说明',
  `CHANGE_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '更新类型，字典CHANGETYPE master：主要更新，minor：次要更新，patch：补丁更新',
  `CHANGE_TXT` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '更新说明',
  `UPGRADE_TIPS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '升级指南',
  `RELEASE_TIME` timestamp(0) NOT NULL COMMENT '发布时间',
  `RES_LINK` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资源连接，json存储，eg：{win:\'url1\',linux:\'url2\',android:\'url3\',iso:\'url4\'}',
  `DEL_FLAG` int(0) NULL DEFAULT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`APP_ID`, `TENANT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：更新日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_change_log
-- ----------------------------
INSERT INTO `sys_change_log` VALUES (1979150713751785472, 100, 1926294804323684352, '1.0.0', 'dev', '{\"header\":[],\"main\":[{\"value\":\"一、主要功能\\n\",\"bold\":true},{\"value\":\"1、基础管理：字典管理，应用管理，配置管理\\n2、组织管理：机构管理，用户管理，角色管理，分组管理，岗位管理\\n3、权限管理：用户权限，角色权限\\n4、统一消息：分类管理、模版管理、消息管理、我的消息\\n5、租户管理：租户维护\\n6、运维管理：操作日志，访问统计，动态订阅，联系我们\",\"bold\":false}],\"footer\":[]}', 'patch', '{\"header\":[],\"main\":[{\"value\":\"本次主要更新内容：\\n1、动态订阅，联系我们\\n2、界面交互完善\\n\"}],\"footer\":[]}', NULL, '2025-10-17 19:41:11', NULL, 0, '2025-10-17 19:41:16', 10000, '2025-10-17 20:31:24', 10000);

