-- Table structure for sys_config_value
-- ----------------------------
DROP TABLE IF EXISTS `sys_config_value`;
CREATE TABLE `sys_config_value`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `CONFIG_ID` bigint(0) NOT NULL COMMENT '配置ID',
  `SN` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '配置编码，从配置根节点的NAM逐层拼接到当前配置NAME,使用“.”分割',
  `TYPES` int(0) NOT NULL COMMENT '类型，字典IUCONFTYPE 0全局，1租户级，2机构级，3用户级',
  `VALUE_USED` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '设置值',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `CONFIG_TENANT_ORG_USER_UNI`(`CONFIG_ID`, `TENANT_ID`, `ORG_ID`, `USER_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：统一配置内容' ROW_FORMAT = Dynamic;

