-- Records of sys_data_define_his
-- ----------------------------
INSERT INTO `sys_data_define_his` VALUES (1874830002909401088, 100, 1000, NULL, 1, 1872260963993440256, '用户信息', 'sys_user', 'BKnfPiUUKI53oYc3AWd0', 1, 'sql', NULL, 0, '2025-01-02 22:47:59', 'select #{page(\'*\')} from sys_user where 1=1 \n\n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}\n-- @if(isNotEmpty(params.lastUpdatedStart)){\n AND LAST_UPDATED > #{params.lastUpdatedStart}\n-- @}\n-- @if(isNotEmpty(params.lastUpdatedEnd)){\n AND LAST_UPDATED <= #{params.lastUpdatedEnd}\n-- @}\n-- @if(isNotEmpty(params.createdStart)){\n AND CREATED > #{params.createdStart}\n-- @}\n-- @if(isNotEmpty(params.createdEnd)){\n AND CREATED <= #{params.createdEnd}\n-- @}\n-- @if(isNotEmpty(params.delFlag)){\n AND DEL_FLAG=#{params.delFlag}\n-- @}\n-- @if(isNotEmpty(params.userType)){\n AND USER_TYPE=#{params.userType}\n-- @}\n-- @if(isNotEmpty(params.username)){\n AND USERNAME LIKE #{\'%\'+params.username+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.realName)){\n AND REAL_NAME LIKE #{\'%\'+params.realName+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.aliasName)){\n AND ALIAS_NAME=#{params.aliasName}\n-- @}\n-- @if(isNotEmpty(params.sex)){\n AND SEX=#{params.sex}\n-- @}\n-- @if(isNotEmpty(params.tel)){\n AND TEL LIKE #{\'%\'+params.tel+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.status)){\n AND STATUS=#{params.status}\n-- @}\n-- @if(isNotEmpty(params.keywords) && !isBlank(params.keywords)){\n AND (USERNAME LIKE #{\'%\'+params.keywords+\'%\'} OR REAL_NAME LIKE #{\'%\'+params.keywords+\'%\'} OR TEL LIKE #{\'%\'+params.keywords+\'%\'})\n-- @}\n #{globalUse(\"base.orderby\")}', 'insert into sys_user(ID,TENANT_ID,ORG_ID,USER_TYPE,USERNAME,PWD_TEXT,PWD_SALT,REAL_NAME,ALIAS_NAME,AVATAR,BIRTHDAY,SEX,EMAIL,QQ,TEL,SECURITY_QUESTION,SUCURITY_MFA,LAST_LOGIN_TIME,LAST_LOGIN_IP,TOTAL_LOGIN_SUCCESS,TOTAL_LOGIN_FAILUE,STATUS,AUDIT_STS,DEL_FLAG,LOCK_TIME,DESCS,CREATED,CREATED_BY,LAST_UPDATED,LAST_UPDATED_BY) values (#{data.id},#{data.tenantId},#{data.orgId},#{data.userType},#{data.username},#{data.pwdText},#{data.pwdSalt},#{data.realName},#{data.aliasName},#{data.avatar},#{data.birthday},#{data.sex},#{data.email},#{data.qq},#{data.tel},#{data.securityQuestion},#{data.sucurityMfa},#{data.lastLoginTime},#{data.lastLoginIp},#{data.totalLoginSuccess},#{data.totalLoginFailue},#{data.status},#{data.auditSts},#{data.delFlag},#{data.lockTime},#{data.descs},#{data.created},#{data.createdBy},#{data.lastUpdated},#{data.lastUpdatedBy})', 'update sys_user set \n-- @trim(){\n-- @if(isNotEmpty(fields.tenantId)){\nTENANT_ID=#{data.tenantId},\n-- @}\n-- @if(isNotEmpty(fields.orgId)){\nORG_ID=#{data.orgId},\n-- @}\n-- @if(isNotEmpty(fields.userType)){\nUSER_TYPE=#{data.userType},\n-- @}\n-- @if(isNotEmpty(fields.username)){\nUSERNAME=#{data.username},\n-- @}\n-- @if(isNotEmpty(fields.pwdText)){\nPWD_TEXT=#{data.pwdText},\n-- @}\n-- @if(isNotEmpty(fields.pwdSalt)){\nPWD_SALT=#{data.pwdSalt},\n-- @}\n-- @if(isNotEmpty(fields.realName)){\nREAL_NAME=#{data.realName},\n-- @}\n-- @if(isNotEmpty(fields.aliasName)){\nALIAS_NAME=#{data.aliasName},\n-- @}\n-- @if(isNotEmpty(fields.avatar)){\nAVATAR=#{data.avatar},\n-- @}\n-- @if(isNotEmpty(fields.birthday)){\nBIRTHDAY=#{data.birthday},\n-- @}\n-- @if(isNotEmpty(fields.sex)){\nSEX=#{data.sex},\n-- @}\n-- @if(isNotEmpty(fields.email)){\nEMAIL=#{data.email},\n-- @}\n-- @if(isNotEmpty(fields.qq)){\nQQ=#{data.qq},\n-- @}\n-- @if(isNotEmpty(fields.tel)){\nTEL=#{data.tel},\n-- @}\n-- @if(isNotEmpty(fields.securityQuestion)){\nSECURITY_QUESTION=#{data.securityQuestion},\n-- @}\n-- @if(isNotEmpty(fields.sucurityMfa)){\nSUCURITY_MFA=#{data.sucurityMfa},\n-- @}\n-- @if(isNotEmpty(fields.lastLoginTime)){\nLAST_LOGIN_TIME=#{data.lastLoginTime},\n-- @}\n-- @if(isNotEmpty(fields.lastLoginIp)){\nLAST_LOGIN_IP=#{data.lastLoginIp},\n-- @}\n-- @if(isNotEmpty(fields.totalLoginSuccess)){\nTOTAL_LOGIN_SUCCESS=#{data.totalLoginSuccess},\n-- @}\n-- @if(isNotEmpty(fields.totalLoginFailue)){\nTOT