INSERT INTO `sys_data_define_his` VALUES (1923551153243869184, 100, 1000, NULL, 1, 1874816956493254656, '操作日志', 'sys_logs', 'b4FSdJl5bhUlcdvECO0V', 1, 'sql', NULL, 0, '2025-05-17 09:28:27', 'select #{page(\'*\')} from sys_logs where 1=1 \n\n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}\n-- @if(isNotEmpty(params.createdStart)){\n AND CREATED > #{params.createdStart}\n-- @}\n-- @if(isNotEmpty(params.createdEnd)){\n AND CREATED <= #{params.createdEnd}\n-- @}\n-- @if(isNotEmpty(params.userName)){\n AND USER_NAME LIKE #{\'%\'+params.userName+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.title)){\n AND TITLE=#{params.title}\n-- @}\n-- @if(isNotEmpty(params.userIdParams) && (isNotEmpty(params.userIdParams.userType) || isNotEmpty(params.userIdParams.realName) || isNotEmpty(params.userIdParams.tel) )){\n AND EXISTS( SELECT 1 FROM sys_user AS fkt WHERE USER_ID = fkt.SID\n-- @if(isNotEmpty(params.userIdParams.userType) && !isBlank(params.userIdParams.userType)){\n AND fkt.USER_TYPE=#{params.userIdParams.userType}\n-- @}\n-- @if(isNotEmpty(params.userIdParams.realName) && !isBlank(params.userIdParams.realName)){\n AND fkt.REAL_NAME LIKE #{\'%\'+params.userIdParams.realName+\'%\'}\n-- @}\n-- @if(isNotEmpty(params.userIdParams.tel) && !isBlank(params.userIdParams.tel)){\n AND fkt.TEL LIKE #{\'%\'+params.userIdParams.tel+\'%\'}\n-- @}\n)\n-- @}\n-- @if(isNotEmpty(params.keywords) && !isBlank(params.keywords)){\n AND (USER_NAME LIKE #{\'%\'+params.keywords+\'%\'})\n-- @}\n #{globalUse(\"base.orderby\")}', 'insert into sys_logs(ID,APP_SN,TENANT_ID,ORG_ID,USER_ID,USER_NAME,ACTION_ID,REQUEST_ID,PREQUEST_ID,TITLE,CONTENTS,TYPES,STATUS,TARGET_ID,START_TIME,END_TIME,IP,EXT_DATA,ERROR_MESSAGE,ERROR_CODE,CREATED,CREATED_BY) values (#{data.id},#{data.appSn},#{data.tenantId},#{data.orgId},#{data.userId},#{data.userName},#{data.actionId},#{data.requestId},#{data.prequestId},#{data.title},#{data.contents},#{data.types},#{data.status},#{data.targetId},#{data.startTime},#{data.endTime},#{data.ip},#{data.extData},#{data.errorMessage},#{data.errorCode},#{data.created},#{data.createdBy})', 'update sys_logs set \n-- @trim(){\n-- @if(isNotEmpty(fields.appSn)){\nAPP_SN=#{data.appSn},\n-- @}\n-- @if(isNotEmpty(fields.tenantId)){\nTENANT_ID=#{data.tenantId},\n-- @}\n-- @if(isNotEmpty(fields.orgId)){\nORG_ID=#{data.orgId},\n-- @}\n-- @if(isNotEmpty(fields.userId)){\nUSER_ID=#{data.userId},\n-- @}\n-- @if(isNotEmpty(fields.userName)){\nUSER_NAME=#{data.userName},\n-- @}\n-- @if(isNotEmpty(fields.actionId)){\nACTION_ID=#{data.actionId},\n-- @}\n-- @if(isNotEmpty(fields.requestId)){\nREQUEST_ID=#{data.requestId},\n-- @}\n-- @if(isNotEmpty(fields.prequestId)){\nPREQUEST_ID=#{data.prequestId},\n-- @}\n-- @if(isNotEmpty(fields.title)){\nTITLE=#{data.title},\n-- @}\n-- @if(isNotEmpty(fields.contents)){\nCONTENTS=#{data.contents},\n-- @}\n-- @if(isNotEmpty(fields.types)){\nTYPES=#{data.types},\n-- @}\n-- @if(isNotEmpty(fields.status)){\nSTATUS=#{data.status},\n-- @}\n-- @if(isNotEmpty(fields.targetId)){\nTARGET_ID=#{data.targetId},\n-- @}\n-- @if(isNotEmpty(fields.startTime)){\nSTART_TIME=#{data.startTime},\n-- @}\n-- @if(isNotEmpty(fields.endTime)){\nEND_TIME=#{data.endTime},\n-- @}\n-- @if(isNotEmpty(fields.ip)){\nIP=#{data.ip},\n-- @}\n-- @if(isNotEmpty(fields.extData)){\nEXT_DATA=#{data.extData},\n-- @}\n-- @if(isNotEmpty(fields.errorMessage)){\nERROR_MESSAGE=#{data.errorMessage},\n-- @}\n-- @if(isNotEmpty(fields.errorCode)){\nERROR_CODE=#{data.errorCode},\n-- @}\n-- @if(isNotEmpty(fields.created)){\nCREATED=#{data.created},\n-- @}\n-- @if(isNotEmpty(fields.createdBy)){\nCREATED_BY=#{data.createdBy},\n-- @}\n-- @}\n where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\n AND ID IN (#{join(params.ids)})\n-- @}', 'DELETE FROM sys_logs where  1=1 \n-- @if(isNotEmpty(params.id)){\n AND ID=#{params.id}\n-- @}\n-- @if(isNotEmpty(params.ids)){\