-- ----------------------------
-- Table structure for sys_data_dir
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_dir`;
CREATE TABLE `sys_data_dir`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `ICON` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标_字体',
  `ICON_PIC` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标_图片',
  `LVSN` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '层级编码',
  `LEVEL` int(0) NOT NULL COMMENT '所在层级',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `DESCS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记,字典TRUEORFALSE 1是0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据目录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_data_dir
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_field
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_field`;
CREATE TABLE `sys_data_field`  (
  `ID` bigint(0) NOT NULL COMMENT '主键',
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DEFINE_ID` bigint(0) NOT NULL COMMENT '数据定义ID',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '名称',
  `DATA_VALUE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '默认值',
  `DATA_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数据类型，直接使用java映射类型，如：String，Double，Float，Boolean，Date 等',
  `DATA_FORMAT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '数据格式',
  `DATA_LEN` int(0) NOT NULL COMMENT '数据长度',
  `DATA_PREC` int(0) NULL DEFAULT NULL COMMENT '数据精度',
  `IS_PK` int(0) NOT NULL COMMENT '是否主键，字典TUREORNOT 1是，0否',
  `IS_NULL` int(0) NOT NULL COMMENT '是否可以为空，字典TUREORNOT 1是，0否',
  `STS_FIELD` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标准字段，关联的标准字段名称',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '字段配置，JSON结构,{}\r\n            {\r\n                fkey:{外键配置，关联字段集合，列表显示控制等等},\r\n                widget:{表单控件配置，默认值，是否只读},\r\n                convert:{转换器配置},\r\n                show:{表单显示配置}\r\n            }',
  `NEED_AUTH` int(0) NOT NULL COMMENT '是否需要授权',
  `SYNC_ENABLE` int(0) NOT NULL COMMENT '同步开关，是否需要同步去到数据库，字典TUREORFALSE 1是，0否',
  `SYNC_FLAG` int(0) NOT NULL COMMENT '同步状态，是否已同步数据库，字典TUREORFALSE 1是，0否',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '使用状态，字典USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：数据字段' ROW_FORMAT = Dynamic;

