CREATE TABLE `sys_logs`  (
  `ID` bigint(0) NOT NULL,
  `APP_SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '应用编码',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `USER_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '用户姓名',
  `ACTION_ID` bigint(0) NULL DEFAULT NULL COMMENT '业务操作ID',
  `REQUEST_ID` bigint(0) NULL DEFAULT NULL COMMENT '业务请求ID',
  `PREQUEST_ID` bigint(0) NULL DEFAULT NULL COMMENT '前置请求ID',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作标题',
  `CONTENTS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '操作内容',
  `TYPES` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '操作类别，字典LOGTYPE query查询，insert新增，update修改，delete删除,login登录，logout注销，resetpwd修改密码',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '操作状态，字典LOGSTATUS 1成功，2失败，3异常',
  `TARGET_ID` bigint(0) NULL DEFAULT NULL COMMENT '目标ID',
  `START_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '开始时间',
  `END_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '完成时间',
  `IP` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '操作IP',
  `EXT_DATA` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '扩展信息，标准json对象存储{}',
  `ERROR_MESSAGE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '异常消息',
  `ERROR_CODE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '异常代码',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `APP_SN`(`APP_SN`) USING BTREE,
  INDEX `TENANT_D`(`TENANT_ID`) USING BTREE,
  INDEX `RG_ID`(`ORG_ID`) USING BTREE,
  INDEX `USER_ID`(`USER_ID`) USING BTREE,
  INDEX `TITLE`(`TITLE`) USING BTREE,
  INDEX `TYPES`(`TYPES`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_logs
-- ----------------------------

-- ----------------------------
-- Table structure for sys_online_doc
-- ----------------------------
DROP TABLE IF EXISTS `sys_online_doc`;
CREATE TABLE `sys_online_doc`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `VERS_NO` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '版本号',
  `ICON_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `PROFILE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '文档介绍',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典ONLINEDOCSTS 1：编制中，2：内审中，3：已发布，4：已归档',
  `RELEASE_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '发布日期',
  `ARCHIVE_TIME` timestamp(0) NULL DEFAULT NULL COMMENT '归档日期',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `APP_ID`, `STATUS`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：在线文档' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_online_doc
-- ----------------------------
INSERT INTO `sys_online_doc` VALUES (1979521348424355840, 100, 1926294804323684352, '系统管理', '1.0.0', 'SettingOutlined', NULL, NULL, NULL, '{\"header\":[],\"main\":[{\"value\":\"系统管理岗位我\"}],\"footer\":[]}', 0, 2, '2025-10-18 20:31:12', '2025-10-18 20:31:18', NULL, 0, '2025-10-18 20:14:02', 10000, '2025-10-18 20:31:23', 10000);
INSERT INTO `sys_online_doc` VALUES (1979701470532128768, 100, 1979369130308063232, 'Uinone Cloud', '1.0.0', 'CloudOutlined', NULL, NULL, NULL, '{\"header\":[],\"main\":[{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"项目介绍\",\"size\":32,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"UniOne Cloud 是一个开源的云管理平台，旨在提供简单、高效、灵活的云资源管理解决方案。本项目适用于各种规模的组织，从个人开发者到大型企业。\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"主要特性\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"统一的资源管理界面，支持多种云服务\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"灵活的权限管理系统，支持细粒度的访问控制\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"强大的自动化部署和管理功能\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"完善的监控和告警机制\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"丰富的API接口，方便集成和扩展\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"开源免费，可定制性强\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false}],\"listType\":\"ul\",\"listStyle\":\"\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"系统架构\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\"},{\"value\":\"UniOne Cloud 采用微服务架构设计，主要包含以下核心组件：\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"API Gateway\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：统一的API入口，负责请求路由、认证和限流\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"User Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：用户管理服务，处理用户认证、授权和配置\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Resource Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：资源管理服务，负责各类资源的创建、监控和管理\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Task Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：任务调度服务，处理异步任务和定时任务\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Monitoring Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：监控服务，收集和分析系统运行数据\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Storage Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：存储服务，管理各类数据存储\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false}],\"listType\":\"ul\",\"listStyle\":\"\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"技术栈\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\\n\"},{\"value\":\"Java\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Spring Boot\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"MySQL\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Git\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Docker\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"HTML5\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"CSS3\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"JavaScript\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"}],\"footer\":[]}', 0, 3, '2025-10-19 11:44:58', NULL, NULL, 0, '2025-10-19 08:09:46', 10000, '2025-10-19 11:44:58', 10000);
INSERT INTO `sys_online_doc` VALUES (1979906927817314304, 100, 1979371119309934592, 'Unione Cms', '1.0.0', NULL, NULL, NULL, NULL, '{\"header\":[],\"main\":[{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"项目简介:\",\"size\":13,\"bold\":true,\"color\":\"rgb(6, 101, 203)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"Unione CMS是基于Unione Cloud构建的内容管理系统，提供快速搭建各类网站的能力，内置丰富的网站模板。本项目致力于为用户提供高效、灵活、易用的内容管理解决方案，适用于企业官网、门户网站、内容平台等多种场景。\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"主要功能\",\"size\":13,\"bold\":true,\"color\":\"rgb(6, 101, 203)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"站点管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：多站点统一管理，支持站点创建、编辑、删除等操作\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点域名绑定\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持多个域名绑定到不同站点\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"栏目管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：灵活的栏目结构设计，支持无限层级分类\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：富文本编辑器，支持图文混排、视频嵌入等\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容发布\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：工作流支持，多级审核机制\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容审核\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持多级审核流程，确保内容质量\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"内容预览\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：实时预览内容展示效果\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"资源管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：统一的媒体资源管理系统\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"开发管理\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持资源在线开发，调试，预览；支持版本管理。\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"资源导入/导出\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持批量资源操作\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点静态化\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持整站静态化，提升访问性能\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"站点导出\",\"size\":13,\"bold\":true,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"：支持站点完整导出，便于迁移和备份\",\"size\":13,\"bold\":false,\"color\":\"rgb(53, 49, 49)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"listType\":\"ul\",\"listStyle\":\"disc\"}],\"footer\":[]}', 0, 1, NULL, NULL, NULL, 0, '2025-10-19 21:46:11', 10000, '2025-10-19 21:46:11', 10000);

-- ----------------------------
-- Table structure for sys_online_doc_item
-- ----------------------------
DROP TABLE IF EXISTS `sys_online_doc_item`;
CREATE TABLE `sys_online_doc_item`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `DOC_ID` bigint(0) NOT NULL COMMENT '文档ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级ID(根节点为-1)',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `ICON_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `CONTENTS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '文档内容',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典 TUREORFALSE 1是，0否',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `DOC_ID`, `PARENT_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：在线文档内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_online_doc_item
-- ----------------------------
