INSERT INTO `sys_online_doc_item` VALUES (1979702935506046976, 100, 1979369130308063232, 1979701470532128768, -1, '快速开始', 'HomeOutlined', NULL, NULL, NULL, NULL, 0, 1, 0, NULL, '2025-10-19 08:15:36', 10000, '2025-10-19 08:24:00', 10000);
INSERT INTO `sys_online_doc_item` VALUES (1979705050685165568, 100, 1979369130308063232, 1979701470532128768, 1979702935506046976, '项目介绍', 'LinkOutlined', NULL, NULL, NULL, '{\"header\":[],\"main\":[{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"项目介绍\",\"size\":32,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"UniOne Cloud 是一个开源的云管理平台，旨在提供简单、高效、灵活的云资源管理解决方案。本项目适用于各种规模的组织，从个人开发者到大型企业。\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false,\"highlight\":\"rgb(255, 255, 255)\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"主要特性\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"统一的资源管理界面，支持多种云服务\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"灵活的权限管理系统，支持细粒度的访问控制\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"强大的自动化部署和管理功能\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"完善的监控和告警机制\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"丰富的API接口，方便集成和扩展\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"开源免费，可定制性强\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false}],\"listType\":\"ul\",\"listStyle\":\"\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"系统架构\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\"},{\"value\":\"UniOne Cloud 采用微服务架构设计，主要包含以下核心组件：\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"API Gateway\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：统一的API入口，负责请求路由、认证和限流\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"User Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：用户管理服务，处理用户认证、授权和配置\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Resource Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：资源管理服务，负责各类资源的创建、监控和管理\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Task Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：任务调度服务，处理异步任务和定时任务\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Monitoring Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：监控服务，收集和分析系统运行数据\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Storage Service\",\"size\":15,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false},{\"value\":\"：存储服务，管理各类数据存储\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false}],\"listType\":\"ul\",\"listStyle\":\"\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"技术栈\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\\n\"},{\"value\":\"Java\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Spring Boot\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"MySQL\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Git\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Docker\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"HTML5\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"CSS3\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"JavaScript\",\"size\":14,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"}],\"footer\":[]}', 1, 1, 0, NULL, '2025-10-19 08:24:00', 10000, '2025-10-19 08:26:33', 10000);
INSERT INTO `sys_online_doc_item` VALUES (1979705586423615488, 100, 1979369130308063232, 1979701470532128768, 1979702935506046976, '安装部署', 'FormatPainterOutlined', NULL, NULL, NULL, '{\"header\":[],\"main\":[{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"安装部署\",\"size\":32,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"本章节介绍如何安装和部署 UniOne Cloud 系统。\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"前提条件\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\",\"type\":\"list\",\"valueList\":[{\"value\":\"\\n\"},{\"value\":\"JDK 11 或更高版本\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"MySQL 5.7 或更高版本\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Redis 5.0 或更高版本\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Maven 3.6 或更高版本（用于编译源码）\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"Docker 和 Docker Compose（可选，用于容器化部署）\",\"size\":15,\"bold\":false,\"color\":\"rgb(44, 62, 80)\",\"italic\":false}],\"listType\":\"ul\",\"listStyle\":\"\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"从源码安装\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\"},{\"value\":\"# 克隆代码库\\n$ git clone https://github.com/unione-cloud/unione.git\\n\\n# 进入项目目录\\n$ cd unione\\n\\n# 编译项目\\n$ mvn clean package -DskipTests\\n\\n# 运行服务\\n$ java -jar unione-web/target/unione-web-*.jar\",\"size\":14,\"bold\":false,\"color\":\"rgb(232, 62, 140)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"Docker 部署\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\"},{\"value\":\"# 克隆代码库\\n$ git clone https://github.com/unione-cloud/unione.git\\n\\n# 进入项目目录\\n$ cd unione\\n\\n# 使用 Docker Compose 启动服务\\n$ docker-compose up -d\",\"size\":14,\"bold\":false,\"color\":\"rgb(232, 62, 140)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"使用 Docker Compose 部署会自动创建并配置所有必要的服务，包括数据库、Redis等。\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false,\"highlight\":\"rgb(255, 243, 205)\"},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"配置环境变量\",\"size\":24,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"third\"},{\"value\":\"\\n\"},{\"value\":\"UniOne Cloud 支持通过环境变量进行配置，常用的环境变量包括：\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"# 数据库配置\\nDB_URL=jdbc:mysql://localhost:3306/unione?useSSL=false&serverTimezone=UTC\\nDB_USERNAME=root\\nDB_PASSWORD=password\\n\\n# Redis 配置\\nREDIS_HOST=localhost\\nREDIS_PORT=6379\\n\\n# 服务器配置\\nSERVER_PORT=8080\\nSERVER_CONTEXT_PATH=/unione\\n\\n# 安全配置\\nADMIN_USERNAME=admin\\nADMIN_PASSWORD=admin123\",\"size\":14,\"bold\":false,\"color\":\"rgb(232, 62, 140)\",\"italic\":false},{\"value\":\"\\n\"},{\"value\":\"\",\"type\":\"title\",\"valueList\":[{\"value\":\"快速开始指南\",\"size\":32,\"bold\":true,\"color\":\"rgb(33, 37, 41)\",\"italic\":false}],\"level\":\"second\"},{\"value\":\"\\n\"},{\"value\":\"本章节将帮助您快速上手 UniOne Cloud，完成基本的配置和使用。\",\"size\":16,\"bold\":false,\"color\":\"rgb(73, 80, 87)\",\"italic\":false},{\"value\":\"\\n\"}],\"footer\":[]}', 1, 1, 0, NULL, '2025-10-19 08:26:08', 10000, '2025-10-19 10:20:35', 10000);
