-- ----------------------------
-- Table structure for sys_resource
-- ----------------------------
DROP TABLE IF EXISTS `sys_resource`;
CREATE TABLE `sys_resource`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `APP_ID` bigint(0) NOT NULL COMMENT '应用ID',
  `PARENT_ID` bigint(0) NOT NULL COMMENT '上级菜单ID(根节点为-1)',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '资源名称/编码，唯一',
  `TITLE` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '资源标题',
  `ALIAS` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资源别名（授权树区别重复菜单名称）',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '资源类型，字典SYSRESTYPE menu：菜单，btn：按钮，tool：工具',
  `PATH` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资源PATH',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资源URL地址',
  `IS_IFRAME` int(0) NULL DEFAULT NULL COMMENT '是否iframe打开，字典TRUEORFALSE 1是，0否',
  `IS_EXTERNAL` int(0) NULL DEFAULT NULL COMMENT '是否外部链接，字典TRUEORFALSE 1是，0否',
  `IS_HIDE` int(0) NULL DEFAULT NULL COMMENT '是否隐藏，字典 TUREORFALSE 1是，0否',
  `IS_LEAF` int(0) NOT NULL COMMENT '是否叶子节点，字典 TUREORFALSE 1是，0否',
  `IS_NEED_PERMIS` int(0) NOT NULL COMMENT '是否需要授权，字典 TUREORFALSE 1是，0否',
  `IS_PLATFORM` int(0) NOT NULL COMMENT '是否平台资源，字典 TUREORFALSE 1是，0否',
  `ICON_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `ORDERED` int(0) NOT NULL COMMENT '显示顺序',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CONFIGS` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '资源设置,JSON存储{}',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`, `CREATED`, `CREATED_BY`, `LAST_UPDATED`, `LAST_UPDATED_BY`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE,
  INDEX `PARENT_ID`(`PARENT_ID`) USING BTREE,
  INDEX `APP_ID`(`APP_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：系统资源' ROW_FORMAT = Dynamic;

