-- ----------------------------
-- Table structure for sys_tenant
-- ----------------------------
DROP TABLE IF EXISTS `sys_tenant`;
CREATE TABLE `sys_tenant`  (
  `ID` bigint(0) NOT NULL,
  `SN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '租户标识',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '租户名称',
  `DOMAIN` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '租户域名,系统访问二级域名',
  `LOGO` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '租户LOGO',
  `LOGIN_AD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '登录广告',
  `REGISTE_WAY` int(0) NOT NULL COMMENT '租户注册方式,字典TENANTREGTYPE 1自主注册，2客服创建',
  `ADMIN_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户管理员帐号ID',
  `LINK_MAN` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系人',
  `LINK_ADD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系地址',
  `LINK_TEL` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系电话',
  `LOCATION_CITY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '所在城市',
  `LOCATION_PROVINCE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '所在省份',
  `OPEN_TIME` datetime(0) NULL DEFAULT NULL COMMENT '开户时间',
  `MAX_USER_COUNT` int(0) NULL DEFAULT NULL COMMENT '最大用户数量',
  `MAX_USER_ONLINE` int(0) NULL DEFAULT NULL COMMENT '最大用户在线数量',
  `MAX_ORGAN_COUNT` int(0) NULL DEFAULT NULL COMMENT '最大机构数量',
  `MAX_ORGAN_USER_COUINT` int(0) NULL DEFAULT NULL COMMENT '每个结构最大用户数',
  `STATUS` int(0) NOT NULL COMMENT '租户状态,字典TENANTSTATUS 1新建，2开通，3关闭',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '租户备注',
  `CREATED` timestamp(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人员',
  `LAST_UPDATED` timestamp(0) NOT NULL COMMENT '更新时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '更新人员',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `SN`(`SN`) USING BTREE,
  UNIQUE INDEX `UNIQUE_NAME`(`NAME`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：租户信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_tenant
-- ----------------------------
