-- ----------------------------
-- Table structure for sys_tool
-- ----------------------------
DROP TABLE IF EXISTS `sys_tool`;
CREATE TABLE `sys_tool`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `TITLE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标题',
  `URL` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'URL',
  `IS_GLOBAL` int(0) NULL DEFAULT NULL COMMENT '是否全局（平台显示）',
  `IS_DEFUALT` int(0) NULL DEFAULT NULL COMMENT '是否默认（租户显示）',
  `IS_PRIVATE` int(0) NULL DEFAULT NULL COMMENT '是否私有',
  `TYPES` int(0) NULL DEFAULT NULL COMMENT '类型，字典TOOLTYPE  1应用，2工具',
  `ANSWER_WAY` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '响应方式，字典ANSWERWAY dialog对话框，drawer抽屉，router路由，page页面（浏览器新tab页）',
  `ICON` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标（字体图标）',
  `PIC_MAX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '大图标(图片图标)',
  `PIC_MID` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '中图标(图片图标)',
  `PIC_MIX` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '小图标(图片图标)',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配置，json格式存储',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：常用工具' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_tool
-- ----------------------------

-- ----------------------------
-- Table structure for sys_tool_mine
-- ----------------------------
DROP TABLE IF EXISTS `sys_tool_mine`;
CREATE TABLE `sys_tool_mine`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `TOOL_ID` bigint(0) NOT NULL COMMENT '工具ID',
  `ORDERED` int(0) NULL DEFAULT NULL COMMENT '显示顺序',
  `STATUS` int(0) NULL DEFAULT NULL COMMENT '状态，字典USEORNOT 1使用，0停用',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CONFIGS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配置，json格式存储',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：常用工具(我的)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_tool_mine
-- ----------------------------

-- ----------------------------
-- Table structure for sys_trend_rss
-- ----------------------------
DROP TABLE IF EXISTS `sys_trend_rss`;
CREATE TABLE `sys_trend_rss`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL,
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID',
  `NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '姓名',
  `EMAIL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮箱',
  `TEL` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '电话',
  `SUBJECT` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '订阅主题，多个逗号分隔，字典RSSSUBJECTS all：所有',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '说明',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NULL DEFAULT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：动态订阅' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_trend_rss
-- ----------------------------

-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NOT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NOT NULL COMMENT '机构ID，用户默认机构',
  `USER_TYPE` int(0) NOT NULL COMMENT '用户类型，字典USERTYPE 1管理员，2普通用户，9其他',
  `USERNAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '登录帐号',
  `PWD_TEXT` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户密码',
  `PWD_SALT` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '密码加密盐',
  `REAL_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '真实姓名',
  `ALIAS_NAME` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '别名',
  `AVATAR` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '头像',
  `BIRTHDAY` date NULL DEFAULT NULL COMMENT '生日，YYYY-MM-DD',
  `SEX` int(0) NULL DEFAULT NULL COMMENT '性别，字典SEX 1女，2男',
  `EMAIL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮箱',
  `QQ` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系qq',
  `TEL` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '联系电话',
  `SECURITY_QUESTION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '密保问题',
  `SUCURITY_MFA` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT 'MFA设备标识',
  `LAST_LOGIN_TIME` datetime(0) NULL DEFAULT NULL COMMENT '上次登录时间',
  `LAST_LOGIN_IP` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '上次登录ip',
  `TOTAL_LOGIN_SUCCESS` bigint(0) NULL DEFAULT NULL COMMENT '累计成功登陆次数',
  `TOTAL_LOGIN_FAILUE` bigint(0) NULL DEFAULT NULL COMMENT '累计失败登陆次数',
  `STATUS` int(0) NOT NULL COMMENT '用户状态，字典USERSTATUS 1正常，2禁用，3注销，4锁定',
  `AUDIT_STS` int(0) NULL DEFAULT NULL COMMENT '审核状态，字典USERAUDITSTS 1待审核，2审核通过，3审核不通过',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，0:正常,1:已删除',
  `LOCK_TIME` datetime(0) NULL DEFAULT NULL COMMENT '锁定时间，锁定时间后才能继续登录',
  `DESCS` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNIQUE_USERNAME`(`USERNAME`) USING BTREE,
  UNIQUE INDEX `UNIQUE_TEL`(`TEL`) USING BTREE,
  INDEX `TENANT_ID`(`TENANT_ID`) USING BTREE,
  INDEX `ORG_ID`(`ORG_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统管理：用户信息' ROW_FORMAT = Dynamic;

