-- ----------------------------
-- Table structure for ums_email_acc
-- ----------------------------
DROP TABLE IF EXISTS `ums_email_acc`;
CREATE TABLE `ums_email_acc`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `SER_ID` bigint(0) NOT NULL COMMENT '邮箱服务ID',
  `SER_NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮箱服务名称',
  `EMAIL` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '邮箱地址',
  `PWD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '邮箱密码，密码加密存储',
  `SHOW_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '显示名称',
  `SEND_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发信名称',
  `CRON` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '定时收取邮件，单位分钟，默认10分钟',
  `PROTOCOL` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '协议类型，字典UMSEMAILPROTOCOL:SMTP，POP3，IMAP',
  `RECV_SER_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收件服务器_地址',
  `RECV_SER_PORT` int(0) NULL DEFAULT NULL COMMENT '收件服务器_端口',
  `RECV_SER_SSL` int(0) NULL DEFAULT NULL COMMENT '收件服务器_SSL，TUREORFALSE 1是，0否',
  `RECV_SER_PROTO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收件服务器_协议',
  `SEND_SER_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件服务器_地址',
  `SEND_SER_PORT` int(0) NULL DEFAULT NULL COMMENT '发件服务器_端口',
  `SEND_SER_SSL` int(0) NULL DEFAULT NULL COMMENT '发件服务器_SSL，TUREORFALSE 1是，0否',
  `SEND_SER_PROTO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件服务器_协议',
  `SER_ADDR` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮件服务器',
  `SIGN_TXT` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件签名',
  `CONFIGS` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件样式，json存储 \r\n            {\r\n                font:{\r\n                    size:字体大小，默认12,\r\n                    family:字体，默认无,\r\n                    color:字体颜色\r\n                },\r\n                answer:回复邮件前缀，回复/Re,\r\n                forward:转发邮件前缀，转发/Fw\r\n            }',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:邮件帐号' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_email_acc
-- ----------------------------

-- ----------------------------
-- Table structure for ums_email_attach
-- ----------------------------
DROP TABLE IF EXISTS `ums_email_attach`;
CREATE TABLE `ums_email_attach`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '用户ID，只有通过邮件服务发送的附件才有附件发送人ID',
  `ACC_ID` bigint(0) NULL DEFAULT NULL COMMENT '帐号ID，只有通过邮件服务发送的附件才有附件发帐号ID',
  `FIEL_ID` bigint(0) NOT NULL COMMENT '文件ID，关联doc服务的fileid',
  `EMAIL_ID` bigint(0) NULL DEFAULT NULL COMMENT '邮件ID',
  `TYPES` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '附件类别，send：发件箱，recv：收件箱',
  `FILE_TITLE` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文件标题',
  `FILE_PATH` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '文件路径',
  `FILE_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文件类型:jpg,doc,png',
  `FILE_SIGN` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文件签名，文件内容MD5签名串',
  `FILE_SIZE` int(0) NOT NULL COMMENT '文件大小，单位字节',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFLASE 1是，0否',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:邮件附件，每个附件（附件名称+文件签名）在doc文档中只有一份。\r\n1、通过我们邮件服务发送邮件的附' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_email_attach
-- ----------------------------

-- ----------------------------
-- Table structure for ums_email_box
-- ----------------------------
DROP TABLE IF EXISTS `ums_email_box`;
CREATE TABLE `ums_email_box`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID，发件人ID',
  `MESSAGE_ID` bigint(0) NULL DEFAULT NULL COMMENT '统一消息ID',
  `MSG_STS_ID` bigint(0) NULL DEFAULT NULL COMMENT '消息状态ID',
  `TODO_ID` bigint(0) NULL DEFAULT NULL COMMENT '待办ID',
  `ACC_ID` bigint(0) NOT NULL COMMENT '邮件帐号ID，发件帐号ID',
  `TMPL_ID` bigint(0) NULL DEFAULT NULL COMMENT '邮件模版ID',
  `REPLY_ID` bigint(0) NULL DEFAULT NULL COMMENT '回复邮件ID，便于会话模式的展现',
  `EMAIL_MSG_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮件消息ID Email Message ID',
  `TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '邮件类型，字典UMSEMAILBOXTYPE send：发送，recv：接收',
  `TOPIC` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '邮件主题',
  `FROM_USER` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件人',
  `RECV_USERS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收件人姓名，多个用逗号分隔，这里显示名称，超出部分显示...',
  `COPY_USERS` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '抄送人姓名，多个用逗号分隔，这里显示名称，超出部分显示...',
  `SCHEDULE_TIME` datetime(0) NULL DEFAULT NULL COMMENT '定时发送时间',
  `SEND_TIME` datetime(0) NULL DEFAULT NULL COMMENT '发送时间',
  `BODY` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '邮件正文',
  `BODY_SIZE` int(0) NULL DEFAULT NULL COMMENT '邮件正文大小，单位kb',
  `ATTACH_SIZE` int(0) NULL DEFAULT NULL COMMENT '邮件附件大小，所有附件大小累计，单位kb',
  `IS_STAR` int(0) NULL DEFAULT NULL COMMENT '是否星标',
  `TAG_VALUE` bigint(0) NULL DEFAULT NULL COMMENT '邮件标签',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典UMSEMAILSTATUS 1草稿，2待发送，3发送中，4已发送，5发送失败，6取消发送',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TRUEORFALSE 1是，0否',
  `CREATED` timestamp(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` timestamp(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `TENANT_ID`, `USER_ID`, `STATUS`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:邮箱，包括发送的邮件和接收的邮件。\r\n发送邮件流程:比较简单，正常发送之外，将邮件SID放入Mess' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_email_box
-- ----------------------------

-- ----------------------------
-- Table structure for ums_email_receiver
-- ----------------------------
DROP TABLE IF EXISTS `ums_email_receiver`;
CREATE TABLE `ums_email_receiver`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `EMAIL_ID` bigint(0) NOT NULL COMMENT '邮件ID',
  `RECV_USER_ID` bigint(0) NULL DEFAULT NULL COMMENT '收件人ID',
  `RECV_ACC_ID` bigint(0) NULL DEFAULT NULL COMMENT '收件帐号ID',
  `RECV_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '收件人类型，字典收件人类型 TO：收件人，CC：抄送人，BCC：密送人',
  `RECV_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '收件地址',
  `RECV_TIME` datetime(0) NULL DEFAULT NULL COMMENT '收件时间',
  `READ_TIME` datetime(0) NULL DEFAULT NULL COMMENT '（首次）查阅时间',
  `TAG_VALUE` bigint(0) NULL DEFAULT NULL COMMENT '标签Value',
  `STAR_FLAG` int(0) NULL DEFAULT NULL COMMENT '星型标记，字典TRUEORFALSE 1是，0否',
  `READ_FLAG` int(0) NULL DEFAULT NULL COMMENT '阅读标记,是否已阅，字典TRUEORFALSE 1是，0否',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`EMAIL_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:邮件收件人' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_email_receiver
-- ----------------------------

-- ----------------------------
-- Table structure for ums_email_server
-- ----------------------------
DROP TABLE IF EXISTS `ums_email_server`;
CREATE TABLE `ums_email_server`  (
  `ID` bigint(0) NOT NULL,
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `NAME` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '服务名称，字典 qq：QQ邮箱，e163：163邮箱，e162：162邮箱',
  `PROTOCOL` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '协议类型，字典UMSEMAILPROTOCOL:SMTP，POP3，IMAP',
  `RECV_SER_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收件服务器_地址',
  `RECV_SER_PORT` int(0) NULL DEFAULT NULL COMMENT '收件服务器_端口',
  `RECV_SER_SSL` int(0) NULL DEFAULT NULL COMMENT '收件服务器_SSL，TUREORFALSE 1是，0否',
  `RECV_SER_PROTO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '收件服务器_协议',
  `SEND_SER_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件服务器_地址',
  `SEND_SER_PORT` int(0) NULL DEFAULT NULL COMMENT '发件服务器_端口',
  `SEND_SER_SSL` int(0) NULL DEFAULT NULL COMMENT '发件服务器_SSL，TUREORFALSE 1是，0否',
  `SEND_SER_PROTO` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '发件服务器_协议',
  `SER_ADDR` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '邮件服务器',
  `STATUS` int(0) NOT NULL COMMENT '状态，字典，使用状态 USEORNOT 1使用，0停用',
  `DEL_FLAG` int(0) NOT NULL COMMENT '删除标记，字典TUREORFALSE 1是，0否',
  `DESCS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '描述',
  `CREATED` datetime(0) NOT NULL,
  `CREATED_BY` bigint(0) NOT NULL,
  `LAST_UPDATED` datetime(0) NOT NULL,
  `LAST_UPDATED_BY` bigint(0) NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息:邮件服务模版，定义好平台支持的邮箱服务信息，如：163邮箱，qq邮箱' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ums_email_server
-- ----------------------------

-- ----------------------------
-- Table structure for ums_message
-- ----------------------------
DROP TABLE IF EXISTS `ums_message`;
CREATE TABLE `ums_message`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `ORG_ID` bigint(0) NULL DEFAULT NULL COMMENT '机构ID',
  `USER_ID` bigint(0) NOT NULL COMMENT '用户ID',
  `TMPL_ID` bigint(0) NULL DEFAULT NULL COMMENT '模板表ID',
  `CATEGORY_ID` bigint(0) NOT NULL COMMENT '分类ID',
  `TYPES` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类别 notice：通知，msg：消息',
  `TITLE` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '标题',
  `BODY_HTML` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '内容html',
  `BODY_TEXT` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '内容text',
  `FROM_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源名称，字典UMSMSGFROM ',
  `IS_CONFIRM` int(0) NOT NULL DEFAULT 0 COMMENT '需要用户进行手动确认  0:不需要 1:需要',
  `CONFIRM_TYPE` int(0) NOT NULL COMMENT '确认类型 1:只有确认按钮 2:拒绝/接受',
  `BIZ_ID` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务ID',
  `BIZ_PARAM` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '业务参数,eg:name=zs&sex=1',
  `PRIORITY` int(0) NULL DEFAULT NULL COMMENT '优先级，字典UMSMSGPRIORITY 1：一级，2：二级，3：三级，4：四级',
  `PUBLIC_DATE` datetime(0) NULL DEFAULT NULL COMMENT '发布时间',
  `OFFLINE_DATE` datetime(0) NULL DEFAULT NULL COMMENT '下线时间',
  `DEL_FLAG` int(0) NULL DEFAULT 0 COMMENT '删除标识 0:未删除 1:已删除',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`DEL_FLAG`, `TENANT_ID`, `TYPES`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：消息记录' ROW_FORMAT = Dynamic;

