CREATE TABLE `ums_message_way`  (
  `ID` bigint(0) NOT NULL COMMENT '主键ID',
  `TENANT_ID` bigint(0) NULL DEFAULT NULL COMMENT '租户ID',
  `MESSAGE_ID` bigint(0) NOT NULL COMMENT '消息ID',
  `WAY` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '通知方式，字典UMSMESSAGEWAY sms：短信，email：邮件，site：站内信',
  `CREATED` datetime(0) NOT NULL COMMENT '创建时间',
  `CREATED_BY` bigint(0) NOT NULL COMMENT '创建人',
  `LAST_UPDATED` datetime(0) NOT NULL COMMENT '修改时间',
  `LAST_UPDATED_BY` bigint(0) NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `NORMAL`(`MESSAGE_ID`, `WAY`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '统一消息：通知方式' ROW_FORMAT = Dynamic;

